<div class="page-title"><div><em>SUPPORT TICKET · <?=$ticket['reference']?></em><h1><?=html_escape($ticket['subject'])?></h1><p><?=html_escape($ticket['first_name'].' '.$ticket['last_name'])?> · <?=html_escape($ticket['email'])?></p></div><span class="<?=status_class($ticket['status'])?>"><?=ucwords(str_replace('_',' ',$ticket['status']))?></span></div><section class="panel conversation"><?php foreach($ticket['messages'] as $message):?><article class="message <?=$message['is_staff']?'staff':''?>"><header><b><?=html_escape($message['first_name'].' '.$message['last_name'])?></b><small><?=$message['is_staff']?'NorthWest support':'Customer'?> · <?=date('M j, Y g:i a',strtotime($message['created_at']))?></small></header><p><?=nl2br(html_escape($message['message']))?></p></article><?php endforeach?><div class="reply-form"><?=form_open('admin/tickets/'.$ticket['id'].'/reply')?><label>Reply</label><textarea name="message" rows="5" required placeholder="Write a helpful response..."></textarea><div><select name="status"><option value="in_progress">Keep in progress</option><option value="resolved">Mark resolved</option><option value="closed">Close ticket</option></select><button class="btn">Send reply</button></div></form></div></section>
